  // 매 바 O(length) 재계산). length/offset/sigma 셋 다 weight 배열의 크기/모양을 최초 호출 값으로
  // 고정하므로 tsi(C49)/macd와 동일하게 lengthArgIndex가 [1, 2, 3] 배열(셋 다 series면 하드 에러). ──

  it("registers a ta.alma call site with its own taSlots slot", () => {
    const prog = analyzeSource("x = ta.alma(close, 9, 0.85, 6)");
    expect(prog.errors).toEqual([]);
    expect(prog.taSlotCount).toBe(1);
    const stmt = prog.script.body[0] as Assignment;
    expect(prog.stateCallSlots.get(stmt.value as CallExpr)).toEqual({ fn: "alma", slot: 0 });
  });

  it("errors on ta.alma call with wrong argument count", () => {
    const prog = analyzeSource("x = ta.alma(close, 9, 0.85)");
    expect(prog.errors.some((e) => e.includes("'ta.alma'") && e.includes("argument count"))).toBe(true);
  });

  it("accepts ta.alma inside a while-body and registers the slot (loop bodies allowed since C161, per-call advance)", () => {
    const prog = analyzeSource("while close > open\n    x = ta.alma(close, 9, 0.85, 6)");
    expect(prog.errors).toEqual([]);
    expect(prog.taSlotCount).toBe(1);
  });

  it("errors when ta.alma's length argument is a bar series identifier directly", () => {
    const prog = analyzeSource("x = ta.alma(close, close, 0.85, 6)");
    expect(prog.errors.some((e) => e.includes("'ta.alma'") && e.includes("length"))).toBe(true);
  });

  it("errors when ta.alma's offset argument is a bar series identifier directly", () => {
    // lengthArgIndex가 [1, 2, 3] 배열이라 length(index 1)뿐 아니라 offset(index 2)도 독립적으로
    // series 하드 에러 대상이어야 한다(tsi의 short/long_length 회귀 가드와 동일 원칙).
    const prog = analyzeSource("x = ta.alma(close, 9, close, 6)");
    expect(prog.errors.some((e) => e.includes("'ta.alma'") && e.includes("length"))).toBe(true);
  });

  it("errors when ta.alma's sigma argument is a bar series identifier directly", () => {
    const prog = analyzeSource("x = ta.alma(close, 9, 0.85, close)");
    expect(prog.errors.some((e) => e.includes("'ta.alma'") && e.includes("length"))).toBe(true);
  });

  it("accepts literal length/offset/sigma arguments for ta.alma (regression guard)", () => {
    const prog = analyzeSource("a = ta.alma(close, 9, 0.85, 6)");
    expect(prog.errors).toEqual([]);
  });

  it("registers a ta.alma call site sharing the taSlots pool with ta.sma (regression guard)", () => {
    const prog = analyzeSource("a = ta.sma(close, 3)\nb = ta.alma(close, 9, 0.85, 6)");
    expect(prog.errors).toEqual([]);
    expect(prog.taSlotCount).toBe(2);
    const [aStmt, bStmt] = prog.script.body as Assignment[];
    expect(prog.stateCallSlots.get(aStmt!.value as CallExpr)).toEqual({ fn: "sma", slot: 0 });
    expect(prog.stateCallSlots.get(bStmt!.value as CallExpr)).toEqual({ fn: "alma", slot: 1 });
  });

