  it("routes method-call style array.push (top-level var receiver, arrayVars path) to the dotted 'array.push' builtin name", () => {
    const prog = analyzeSource(["var arr = array.new_float(0)", "arr.push(close)"].join("\n"));
    expect(prog.errors).toEqual([]);
    const stmt = prog.script.body[1] as ExprStmt;
    const call = stmt.expr as CallExpr;
    expect(prog.builtinCalls.get(call)).toBe("array.push");
    const receiver = prog.methodCallReceivers.get(call);
    expect(receiver?.kind).toBe("Identifier");
    expect((receiver as { name: string }).name).toBe("arr");
  });

  it("routes method-call style array.push for a '=' local receiver (containerKindHints path, not arrayVars)", () => {
    const prog = analyzeSource(["arr = array.new_float(0)", "arr.push(close)"].join("\n"));
    expect(prog.errors).toEqual([]);
    expect(prog.arrayVars.has("arr")).toBe(false);
    const stmt = prog.script.body[1] as ExprStmt;
    expect(prog.builtinCalls.get(stmt.expr as CallExpr)).toBe("array.push");
  });

  it("routes method-call style map.put (top-level var receiver, mapVars path) to the dotted 'map.put' builtin name", () => {
    const prog = analyzeSource(["var m = map.new<string, float>()", 'm.put("k", 1.0)'].join("\n"));
    expect(prog.errors).toEqual([]);
    const stmt = prog.script.body[1] as ExprStmt;
    expect(prog.builtinCalls.get(stmt.expr as CallExpr)).toBe("map.put");
  });

  it("routes method-call style map.get for a '=' local receiver (containerKindHints path, not mapVars)", () => {
    const prog = analyzeSource(["m = map.new<string, float>()", 'x = m.get("k")'].join("\n"));
    expect(prog.errors).toEqual([]);
    expect(prog.mapVars.has("m")).toBe(false);
    const stmt = prog.script.body[1] as Assignment;
    expect(prog.builtinCalls.get(stmt.value as CallExpr)).toBe("map.get");
  });

  it("errors on method-call style array.push() with 0 explicit arguments (receiverOffset accounted: effective 1 of 2)", () => {
    const prog = analyzeSource(["var arr = array.new_float(0)", "arr.push()"].join("\n"));
    expect(prog.errors.some((e) => e.includes("array.push") && e.includes("1 passed"))).toBe(true);
  });

  it("folds the sort() order-string literal correctly under method-call style (order arg shifts from args[1] to args[0])", () => {
    const prog = analyzeSource(["arr = array.from(3.0, 1.0, 2.0)", 'arr.sort("descending")'].join("\n"));
    expect(prog.errors).toEqual([]);
    const stmt = prog.script.body[1] as ExprStmt;
    const call = stmt.expr as CallExpr;
    const orderArg = call.args[0]! as StringLiteral;
    expect(prog.builtinBooleanConstants.get(orderArg)).toBe(false);
  });

  it("routes method-call style calls for a UDF parameter receiver whose container kind is inferred from a top-level call-site argument (C492 upgrade — was 'no value-flow tracking, unsupported' pre-C492; the call-site scan is narrower than full dataflow but does cover this exact shape)", () => {
    const prog = analyzeSource(["f(a) =>", "    a.push(1.0)", "var arr = array.new_float(0)", "s = f(arr)"].join("\n"));
    expect(prog.errors).toEqual([]);
    expect(prog.funcs.get("f")?.paramContainerKinds.get("a")).toBe("array");
  });

  it("routes method-call style calls for a UDF parameter receiver when the UDF has zero call sites anywhere in the script (C678 dead-code placeholder — TV still compiles unreachable UDF bodies, value never observed so 'array' is a safe default)", () => {
    const prog = analyzeSource(["f(a) =>", "    a.push(1.0)"].join("\n"));
    expect(prog.errors).toEqual([]);
  });

  // ── method-call 스타일 matrix 콜(C237, corpus 재스캔 실측 `m.det()`/`m.transpose()`/`m.rank()`/
